import { createHash } from 'node:crypto';
import { DATA_VERSION } from './version.mjs';
const fail = (status, message) => Object.assign(new Error(message), {status});
const id = v => { const s=String(v ?? ''); if (!/^[1-9]\d{0,15}$/.test(s)) throw fail(400,'invalid_player'); return s; };
const requestId = v => { if (typeof v !== 'string' || !/^[A-Za-z0-9_-]{16,128}$/.test(v)) throw fail(400,'invalid_request_id'); return v; };
const canonical = v => v === null || typeof v !== 'object' ? JSON.stringify(v) : Array.isArray(v) ? '[' + v.map(canonical).join(',') + ']' : '{' + Object.keys(v).sort().map(k => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
const digest = v => createHash('sha256').update(canonical(v)).digest('hex');
const one = async (db,sql,args=[]) => (await db.query(sql,args)).rows[0];
const amountField = {gold:'money',gem:'gems',love:'love'};
export function createRepository(db) {
  async function locked(tx, player) { const row=await one(tx,'SELECT state, revision, data_version FROM hotels WHERE player_id=$1 FOR UPDATE',[player]); if (!row) throw fail(404,'hotel_not_found'); if (row.data_version !== DATA_VERSION) throw fail(409,'unsupported_data_version'); return row; }
  async function save(tx,player,state,revision) { await tx.query('UPDATE hotels SET state=$2, revision=$3 WHERE player_id=$1',[player,JSON.stringify(state),revision]); }
  async function once(tx,player,kind,input,operation) {
    const key=requestId(input.requestId), payload=digest([kind,input]);
    const old=await one(tx,'SELECT payload_hash,response FROM requests WHERE player_id=$1 AND request_id=$2',[player,key]);
    if (old) { if (old.payload_hash !== payload) throw fail(409,'request_id_reused'); return old.response; }
    const result=await operation();
    await tx.query('INSERT INTO requests(player_id,request_id,payload_hash,response) VALUES($1,$2,$3,$4)',[player,key,payload,JSON.stringify(result)]);
    return result;
  }
  async function areFriends(tx,a,b) { return !!await one(tx,'SELECT 1 FROM friendships WHERE accepted=TRUE AND ((requester=$1 AND recipient=$2) OR (requester=$2 AND recipient=$1))',[a,b]); }
  return {
    async register(name,password,state) { try { return await db.transaction(async tx=>{const p=await one(tx,'INSERT INTO players(name,password_hash) VALUES($1,$2) RETURNING id,name',[name,password]); await tx.query('INSERT INTO hotels(player_id,state) VALUES($1,$2)',[p.id,JSON.stringify(state)]); return p;}); } catch(e) { if(e.code==='23505') throw fail(409,'name_taken'); throw e; } },
    findPlayer(name) { return one(db,'SELECT id,name,password_hash FROM players WHERE name=$1',[name]); },
    createSession(token,player,csrf,expires) { return db.query('INSERT INTO sessions(token_hash,player_id,csrf,expires_at) VALUES($1,$2,$3,$4)',[token,player,csrf,expires]); },
    session(token,now) { return one(db,'SELECT s.player_id,s.csrf,p.name FROM sessions s JOIN players p ON p.id=s.player_id WHERE s.token_hash=$1 AND s.expires_at>$2',[token,now]); },
    deleteSession(token) { return db.query('DELETE FROM sessions WHERE token_hash=$1',[token]); },
    async hotel(player,core,clock=Date.now) { player=id(player); return db.transaction(async tx=>{const h=await locked(tx,player),now=Math.max(clock(),h.state.lastRealTime); if(core && (now>h.state.lastRealTime || h.state.flags.some(f=>f.startsWith("server_tutorial_")))) {const sync=core.resumeHotel(h.state,now); await save(tx,player,sync.state,Number(h.revision)+1); return {state:sync.state,revision:Number(h.revision)+1,serverTime:now};} return {state:h.state,revision:Number(h.revision),serverTime:now};}); },
    async command(player,input,core) { player=id(player); if (!Number.isSafeInteger(input.revision) || input.revision<0 || !input.command || typeof input.command!=='object') throw fail(400,'invalid_command'); return db.transaction(async tx=>{const h=await locked(tx,player); return once(tx,player,'command',input,async()=>{if(Number(h.revision)!==input.revision) throw fail(409,'revision_conflict'); const now=Math.max(Date.now(),h.state.lastRealTime), result=core.execute(h.state,now,input.command); if(result.state) { await save(tx,player,result.state,Number(h.revision)+1); } return {...result,revision:Number(h.revision)+(result.state?1:0),serverTime:now};});}); },
    async friends(player) { player=id(player); return {friends:(await db.query('SELECT p.id,p.name FROM friendships f JOIN players p ON p.id=CASE WHEN f.requester=$1 THEN f.recipient ELSE f.requester END WHERE f.accepted=TRUE AND (f.requester=$1 OR f.recipient=$1) ORDER BY p.name',[player])).rows, requests:(await db.query('SELECT p.id,p.name FROM friendships f JOIN players p ON p.id=f.requester WHERE f.recipient=$1 AND f.accepted=FALSE ORDER BY p.name',[player])).rows}; },
    async friendRequest(player,target) { player=id(player); target=id(target); if(player===target) throw fail(400,'invalid_player'); return db.transaction(async tx=>{const a=BigInt(player)<BigInt(target)?player:target, b=a===player?target:player; await locked(tx,a); await locked(tx,b); if(!await one(tx,'SELECT id FROM players WHERE id=$1',[target])) throw fail(404,'player_not_found'); if(await one(tx,'SELECT 1 FROM friendships WHERE (requester=$1 AND recipient=$2) OR (requester=$2 AND recipient=$1)',[player,target])) throw fail(409,'friendship_exists'); await tx.query('INSERT INTO friendships(requester,recipient) VALUES($1,$2)',[player,target]); return {ok:true};}); },
    async friendAccept(player,target) { player=id(player); target=id(target); const result=await db.query('UPDATE friendships SET accepted=TRUE WHERE requester=$1 AND recipient=$2 AND accepted=FALSE RETURNING requester',[target,player]); if (!result.rows.length) throw fail(404,'request_not_found'); return {ok:true}; },
    async visit(player,target,core,clock=Date.now) { player=id(player); target=id(target); return db.transaction(async tx=>{const h=await locked(tx,target); if(!await areFriends(tx,player,target)) throw fail(403,'friendship_required'); const owner=await one(tx,'SELECT name FROM players WHERE id=$1',[target]); const now=Math.max(clock(),h.state.lastRealTime); let state=h.state; if(core && now>state.lastRealTime) {state=core.sync(state,now).state;} state=structuredClone(state); state.messages=[]; state.inventory=[]; state.curQuests=[]; state.stats=[]; state.flags=state.flags.filter(flag=>!flag.startsWith('love_') && !flag.startsWith('server_tutorial_')); state.tasks=state.tasks.filter(task=>!(task.command?.tag==='InternalSetFlag' && String(task.command.args?.[0]).startsWith('love_'))); state.money=0; state.gems=0; state.love=0; return {owner:{id:target,name:owner.name},state,serverTime:now};}); },
    async visitLove(player,target,input,core) { player=id(player); target=id(target); if (player===target || Number(target)>2147483647) throw fail(400,'invalid_player'); return db.transaction(async tx=>{const a=BigInt(player)<BigInt(target)?player:target, b=a===player?target:player; const first=await locked(tx,a),second=await locked(tx,b),h=a===player?first:second,t=a===player?second:first; return once(tx,player,'love',{...input,target},async()=>{if(!await areFriends(tx,player,target)) throw fail(403,'friendship_required'); const now=Math.max(Date.now(),h.state.lastRealTime,t.state.lastRealTime); if(now>t.state.lastRealTime) {t.state=core.sync(t.state,now).state;} const result=core.visitLove(h.state,t.state,Number(target),now); if(!result.state) throw fail(500,'solver_error'); await save(tx,player,result.state,Number(h.revision)+1); return {...result,revision:Number(h.revision)+1,serverTime:now};});}); },
    async gifts(player) { return {gifts:(await db.query('SELECT id,sender,recipient,kind,amount,claimed FROM gifts WHERE sender=$1 OR recipient=$1 ORDER BY (recipient=$1 AND NOT claimed) DESC, id DESC LIMIT 100',[id(player)])).rows}; },
    async sendGift(player,input) { player=id(player); const target=id(input.toPlayerId), field=amountField[input.kind]; if(!Object.hasOwn(amountField,input.kind) || !Number.isSafeInteger(input.amount) || input.amount<1 || input.amount>1000 || target===player) throw fail(400,'invalid_gift'); return db.transaction(async tx=>{const a=BigInt(player)<BigInt(target)?player:target, b=a===player?target:player; const first=await locked(tx,a); const second=await locked(tx,b); const h=a===player?first:second; return once(tx,player,'gift',input,async()=>{if(!await areFriends(tx,player,target)) throw fail(403,'friendship_required'); if(h.state[field]<input.amount) throw fail(409,'insufficient_funds'); h.state[field]-=input.amount; await save(tx,player,h.state,Number(h.revision)+1); const gift=await one(tx,'INSERT INTO gifts(sender,recipient,kind,amount) VALUES($1,$2,$3,$4) RETURNING id,sender,recipient,kind,amount,claimed',[player,target,input.kind,input.amount]); return {ok:true,gift,revision:Number(h.revision)+1};});}); },
    async claimGift(player,giftId,input,core) { player=id(player); giftId=id(giftId); return db.transaction(async tx=>{const h=await locked(tx,player); return once(tx,player,'claim',{...input,giftId},async()=>{const gift=await one(tx,'SELECT * FROM gifts WHERE id=$1 AND recipient=$2 FOR UPDATE',[giftId,player]); if(!gift) throw fail(404,'gift_not_found'); if(gift.claimed) throw fail(409,'already_claimed'); const field=amountField[gift.kind]; if(!field || h.state[field]>2147483647-gift.amount || (gift.kind==='love' && (!core || h.state.love+gift.amount>core.maxLove(h.state)))) throw fail(409,'balance_limit'); h.state[field]+=gift.amount; await save(tx,player,h.state,Number(h.revision)+1); await tx.query('UPDATE gifts SET claimed=TRUE WHERE id=$1',[giftId]); return {ok:true,revision:Number(h.revision)+1};});}); }
  };
}
export function postgresDatabase(pool) { return {query:(...args)=>pool.query(...args), async transaction(fn) { const client=await pool.connect(); try { await client.query('BEGIN'); const result=await fn(client); await client.query('COMMIT'); return result; } catch(e) { await client.query('ROLLBACK'); throw e; } finally { client.release(); } }}; }
